<template><form class="booking-form" @submit.prevent="submit"><div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><div class="form-grid"><label>Дата<input v-model="form.date" required type="date" :min="tomorrow" /></label><label>Время<select v-model="form.time" required><option v-for="time in times" :key="time">{{ time }}</option></select></label><label>Гостей<select v-model.number="form.guests" required><option v-for="count in 12" :key="count" :value="count">{{ count }}</option></select></label><label>Комментарий <span class="meta">необязательно</span><textarea v-model.trim="form.comment" maxlength="200" rows="3" placeholder="Например, детский стул"></textarea></label></div><button class="btn btn-clay" :disabled="busy" type="submit">{{ busy ? 'Сохраняем…' : submitLabel }}</button></form></template><script setup>import { reactive, ref, watch } from 'vue'; const props = defineProps({ initial: { type: Object, default: () => ({}) }, submitLabel: { type: String, default: 'Подтвердить бронь' }, busy: Boolean, error: String }); const emit = defineEmits(['submit']); const format = (date) => date.toISOString().slice(0,10); const date = new Date(); date.setDate(date.getDate()+1); const tomorrow = format(date); const times = ['16:00','17:00','18:00','19:00','20:00','21:00','22:00']; const form = reactive({ date: props.initial.date || tomorrow, time: props.initial.time || '19:00', guests: Number(props.initial.guests || 2), comment: props.initial.comment || '' }); watch(() => props.initial, (next) => Object.assign(form, { date: next.date || tomorrow, time: next.time || '19:00', guests: Number(next.guests || 2), comment: next.comment || '' }), { deep: true }); const submit = () => emit('submit', { ...form });</script>
